<aside class="sidebar"><section class="panel welcome-card glass"><div class="row between"><span class="sidebar-label"><?= t('Member center') ?></span><?= icon('sun') ?></div><h3><?= $me ? e($me['display_name']) . ' / ' . t('Good to see you') : t('Welcome back') ?></h3><p><?= e($s->get('site_tagline')) ?></p><?php if ($me && $s->enabled('checkin')): ?><?= form_start('checkin') ?><?= button($me['last_checkin'] === date('Y-m-d') ? 'Already checked in today' : 'Daily check-in','full','sun') ?></form><?php elseif (!$me): ?><a class="btn full" href="<?= e(url($s->enabled('registration') ? 'register':'login')) ?>"><?= t('Create an account') ?><?= icon('arrow') ?></a><?php else: ?><a class="btn full" href="<?= e(url('profile')) ?>"><?= t('Your profile') ?><?= icon('arrow') ?></a><?php endif ?><?php if(!$me): ?><a class="welcome-foot" href="<?= e(url('login')) ?>"><?= t('Already registered? Sign in') ?></a><?php endif ?></section>
<?php if ($s->get('notice')): ?><section class="panel notice-card glass"><div class="widget-title"><?= icon('bell') ?><h3><?= t('A note from the island') ?></h3></div><p><?= nl2br(e($s->get('notice'))) ?></p></section><?php endif ?>
<?php if ($s->get('promo_enabled') && $s->enabled((string)$s->get('promo_route'))): ?><section class="promo-card"><span class="promo-icon"><?= icon('crown') ?></span><h3><?= e($s->get('promo_title')) ?></h3><p><?= e($s->get('promo_description')) ?></p><a class="text-link" href="<?= e(url($s->get('promo_route'))) ?>"><?= t('Take a closer look') ?><?= icon('arrow') ?></a></section><?php endif ?>
<?php if ($s->enabled('articles')): $recent=$a->content->feed('article',$me,['sort'=>'popular','size'=>4])['items']; ?><section class="panel glass"><div class="widget-title"><?= icon('compass') ?><h3><?= t('Worth a closer look') ?></h3></div><div class="mini-list"><?php foreach ($recent as $n=>$entry): ?><a class="mini-item" href="<?= e(item_url($entry)) ?>"><span class="mini-number">0<?= $n+1 ?></span><div><strong><?= e($entry['title']) ?></strong><?php if ($s->get('show_dates')): ?><small><?= dt((int)$entry['created_at']) ?></small><?php endif ?></div></a><?php endforeach ?></div></section><?php endif ?></aside>
